library(tidyverse)
library(lubridate)
library(arrow)
library(scales)
# Run from repository root; use an explicit path to avoid dependence on the caller's location.
root_dir <- "/home/karthik/apps/bangalore-weather"
out_path <- file.path(root_dir,"docs/assets/analysis/bangalore-sep-14-2026-rain-arrival.png")
d <- open_dataset(file.path(root_dir,"data/weatherunion_bengaluru_hourly.parquet"))
start_ist <- as.POSIXct("2026-09-14 00:00:00",tz="Asia/Kolkata")
end_ist <- as.POSIXct("2026-09-15 00:00:00",tz="Asia/Kolkata")
w <- d %>% filter(hour_ist >= start_ist, hour_ist < end_ist) %>% select(locality_id,current_locality_name,hour_ist,rain_mm) %>% collect() %>% arrange(locality_id,hour_ist) %>% group_by(locality_id) %>% mutate(hour=hour(hour_ist)) %>% ungroup()
onsets <- w %>% filter(!is.na(rain_mm),rain_mm>0.1) %>% group_by(locality_id,current_locality_name) %>% summarise(first_rain_hour=min(hour),.groups="drop")
daily <- w %>% group_by(locality_id,current_locality_name) %>% summarise(valid_rain_hours=sum(!is.na(rain_mm)),rain_mm=sum(rain_mm,na.rm=TRUE),.groups="drop") %>% mutate(rain_mm=if_else(valid_rain_hours==24,rain_mm,NA_real_)) %>% left_join(onsets,by=c("locality_id","current_locality_name"))
station_order <- daily %>% mutate(sort_total=replace_na(rain_mm,-Inf),first_rain_hour=replace_na(first_rain_hour,25L)) %>% arrange(desc(sort_total),first_rain_hour) %>% pull(current_locality_name)
heat_data <- w %>% mutate(station=factor(current_locality_name,levels=rev(station_order)),rain_for_tile=replace_na(rain_mm,0))
base_theme <- theme_minimal(base_size=10) + theme(plot.background=element_rect(fill="white",colour=NA),panel.background=element_rect(fill="white",colour=NA),panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),axis.text=element_text(colour="#3c3c3c"),plot.title=element_text(face="bold",colour="#3c3c3c"),plot.subtitle=element_text(colour="#666666"),plot.caption=element_text(colour="#666666",size=8))
p <- ggplot(heat_data,aes(hour,station,fill=rain_for_tile)) + geom_tile(width=.96,height=.86) + geom_text(data=daily %>% mutate(station=factor(current_locality_name,levels=rev(station_order)),total_label=if_else(rain_mm>0,paste0(number(rain_mm,accuracy=.1)," mm"),"0.0 mm")),aes(x=24.35,y=station,label=total_label),inherit.aes=FALSE,hjust=0,size=2.7,colour="#3c3c3c") + scale_fill_gradient(low="#f3f7f8",high="#176b87",trans="sqrt",breaks=c(0,1,5,20,60),labels=label_number(suffix=" mm"),name="Hourly rain") + scale_x_continuous(breaks=c(0,6,12,18,23),limits=c(-.5,26),labels=function(x)ifelse(x<24,sprintf("%02d:00",x),"")) + labs(title="Rainfall by station - 14 September 2026",subtitle="Rows are ordered by total rainfall, highest first; darker cells mean more rain in that hour",x="Hour (IST)",y=NULL,caption="The first coloured cell in a row marks the first hourly window with >0.1 mm; totals at right. Station observations, not area-wide estimates.") + base_theme + theme(axis.text.y=element_text(size=8),panel.grid=element_blank(),plot.margin=margin(10,70,10,10))
ggsave(out_path,p,width=12,height=9,dpi=180,bg="white")
print(daily %>% arrange(desc(rain_mm)) %>% select(current_locality_name,rain_mm,first_rain_hour))
